    let regionParallelId=''; const openParallelRegionDialog=(parallelId)=>{regionParallelId=parallelId;regionIdInput.value='';regionInitialInput.value='';regionDialogError.textContent='';regionDialog.showModal();setTimeout(()=>regionIdInput.focus(),0);}; const submitRegion=()=>{const regionId=regionIdInput.value.trim(),initialStateId=regionInitialInput.value.trim();if(!regionId||!initialStateId){regionDialogError.textContent='Region ID and initial child ID are required.';return;}if(positions[regionId]||positions[initialStateId]){regionDialogError.textContent='Region and child IDs must be unique.';return;}vscode.postMessage({command:'createParallelRegion',region:{parallelId:regionParallelId,regionId,initialStateId}});regionDialog.close();regionParallelId='';};
