    function updateEdges(){const groups=[...document.querySelectorAll('.edge-group')];const pairCounts=new Map();groups.forEach(group=>{const a=group.dataset.source,b=group.dataset.target,key=a<b?a+'|'+b:b+'|'+a;pairCounts.set(key,(pairCounts.get(key)||0)+1);});const pairLanes=new Map();groups.forEach(group=>{const source=stateBounds(group.dataset.source),target=stateBounds(group.dataset.target);if(!source||!target)return;const {x1,y1,x2,y2}=connectionPoints(source,target);const a=group.dataset.source,b=group.dataset.target,key=a<b?a+'|'+b:b+'|'+a;const lane=pairLanes.get(key)||0;pairLanes.set(key,lane+1);const count=pairCounts.get(key)||1;const dx=x2-x1,dy=y2-y1,length=Math.hypot(dx,dy)||1;const normalX=-dy/length,normalY=dx/length;const laneOffset=count>1?(lane-(count-1)/2)*36:0;const directionSign=a<b?1:-1;const offset=laneOffset*directionSign;const c1x=x1+dx*0.28+normalX*offset,c1y=y1+dy*0.28+normalY*offset,c2x=x2-dx*0.28+normalX*offset,c2y=y2-dy*0.28+normalY*offset;const d='M '+x1+' '+y1+' C '+c1x+' '+c1y+', '+c2x+' '+c2y+', '+x2+' '+y2;group.querySelectorAll('path').forEach(path=>path.setAttribute('d',d));const label=group.querySelector('text'),labelX=(x1+x2)/2+normalX*offset,labelY=(y1+y2)/2+normalY*offset-8;label.setAttribute('x',String(labelX));label.setAttribute('y',String(labelY));const hit=group.querySelector('.transition-label-hit'),labelWidth=Math.max(80,label.textContent.length*7+20);hit.setAttribute('x',String(labelX-labelWidth/2));hit.setAttribute('y',String(labelY-18));hit.setAttribute('width',String(labelWidth));hit.setAttribute('height','28');});}
